package android.content;
public final class ContentValues {private final java.util.Map<String,Object> values=new java.util.HashMap<>();public void put(String key,Long value){values.put(key,value);}public void put(String key,String value){values.put(key,value);}public void putNull(String key){values.put(key,null);}public Object get(String key){return values.get(key);}public String getAsString(String key){Object value=values.get(key);return value==null?null:value.toString();}public Long getAsLong(String key){Object value=values.get(key);return value==null?null:value instanceof Number?((Number)value).longValue():Long.parseLong(value.toString());}}
